CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(254) NOT NULL, password VARCHAR(255) NOT NULL, display_name VARCHAR(50) NOT NULL, age_group VARCHAR(20), education VARCHAR(100), occupation VARCHAR(100), prefecture VARCHAR(20), biography VARCHAR(1000), role VARCHAR(20) NOT NULL, suspended BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT uk_users_email UNIQUE(email));
CREATE TABLE categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(60) NOT NULL, slug VARCHAR(80) NOT NULL, display_order INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT uk_categories_slug UNIQUE(slug));
CREATE TABLE tags (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(50) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT uk_tags_name UNIQUE(name));
CREATE TABLE experience_posts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, author_id BIGINT NOT NULL, category_id BIGINT NOT NULL, title VARCHAR(150) NOT NULL, age_at_choice INT, status_at_choice VARCHAR(100), current_age_group VARCHAR(20), years_elapsed INT, situation_before VARCHAR(3000) NOT NULL, worries VARCHAR(3000) NOT NULL, alternatives VARCHAR(3000) NOT NULL, choice_made VARCHAR(3000) NOT NULL, reason VARCHAR(3000) NOT NULL, outcome VARCHAR(5000) NOT NULL, good_things VARCHAR(3000) NOT NULL, difficulties VARCHAR(3000) NOT NULL, unexpected_things VARCHAR(3000) NOT NULL, satisfaction INT NOT NULL, regret INT NOT NULL, choose_again BOOLEAN NOT NULL, advice_to_past_self VARCHAR(3000) NOT NULL, published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES categories(id), CHECK(satisfaction BETWEEN 1 AND 10), CHECK(regret BETWEEN 1 AND 10));
CREATE TABLE experience_post_tags (post_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, PRIMARY KEY(post_id,tag_id), FOREIGN KEY(post_id) REFERENCES experience_posts(id), FOREIGN KEY(tag_id) REFERENCES tags(id));
CREATE TABLE life_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id BIGINT NOT NULL, age_label VARCHAR(20), title VARCHAR(100) NOT NULL, description VARCHAR(1000), display_order INT NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY(post_id) REFERENCES experience_posts(id));
CREATE TABLE reactions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, post_id BIGINT NOT NULL, type VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(post_id) REFERENCES experience_posts(id), CONSTRAINT uk_reaction_user_post_type UNIQUE(user_id,post_id,type));
CREATE TABLE comments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id BIGINT NOT NULL, author_id BIGINT NOT NULL, body VARCHAR(2000) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY(post_id) REFERENCES experience_posts(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE consultations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, author_id BIGINT NOT NULL, title VARCHAR(150) NOT NULL, body VARCHAR(5000) NOT NULL, age_group VARCHAR(20), current_situation VARCHAR(1000) NOT NULL, options_considering VARCHAR(2000) NOT NULL, open_flag BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE consultation_tags (consultation_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, PRIMARY KEY(consultation_id,tag_id), FOREIGN KEY(consultation_id) REFERENCES consultations(id), FOREIGN KEY(tag_id) REFERENCES tags(id));
CREATE TABLE consultation_answers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, consultation_id BIGINT NOT NULL, author_id BIGINT NOT NULL, body VARCHAR(4000) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY(consultation_id) REFERENCES consultations(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recipient_id BIGINT NOT NULL, type VARCHAR(30) NOT NULL, message VARCHAR(200) NOT NULL, reference_id BIGINT, read_flag BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY(recipient_id) REFERENCES users(id));
CREATE TABLE reports (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, reporter_id BIGINT NOT NULL, target_type VARCHAR(30) NOT NULL, target_id BIGINT NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, FOREIGN KEY(reporter_id) REFERENCES users(id));
